def run(context):
    from datetime import datetime
    current_quarter_start = datetime(datetime.now().year, ((datetime.now().month - 1) // 3) * 3 + 1, 1)
    return {'is_fresh': context['run_ts'] >= current_quarter_start}

def run(context):
    input_data = context.get('scores.stage_snapshots', [])
    gaps_exceptions = []
    for record in input_data:
        if record.get('stage_score', 0) < 50 and record.get('rsi', 0) > 70:
            gaps_exceptions.append(record)
    return {'gaps_exceptions': gaps_exceptions}

def run(context):
    run_data = context.get('enhanced_run_data', [])
    stock_data = context.get('filtered_stock_data', [])
    issues = []
    if any(stock['score'] is None for stock in stock_data):
        issues.append('Missing stock scores found.')
    if any(run['stocks_filtered'] < 0 for run in run_data):
        issues.append('Negative stocks filtered found.')
    return {'incomplete_data_issues': issues}

def run(context):
    holdings_data = context.get('holdings_data', [])
    high_stage = [h for h in holdings_data if h.get('stage_score', 0) > 0]  # Assuming a threshold exists
    add_candidates = [h for h in high_stage if h.get('trading_signal') == 'buy']
    trim_candidates = [h for h in high_stage if h.get('trading_signal') == 'sell']
    return {'add_candidates': add_candidates, 'trim_candidates': trim_candidates, 'risk_flags': []}

